CREATE VIEW finances.holdings_report_rows AS SELECT MIN(external_id::TEXT)::UUID AS external_id, wallet_id, kind, name, ticker, type_label, CASE WHEN SUM(quantity) IS NOT NULL AND SUM(quantity) <> 0 THEN SUM(current_value) / SUM(quantity) ELSE MAX(current_price) END AS current_price, SUM(quantity) AS quantity, SUM(cost_basis) AS cost_basis, SUM(current_value) AS current_value FROM finances.holdings_overview WHERE status = 'ACTIVE' GROUP BY wallet_id, kind, name, ticker, type_label;
